SET NOCOUNT ON;SET XACT_ABORT ON;SET LOCK_TIMEOUT 30000;EXEC fwk.USP_WaitForSignal '$(DemoId)','$(RunToken)','BLOCKER_LOCKED',15000;EXEC fwk.USP_Signal '$(DemoId)','$(RunToken)','WAITER_STARTED';UPDATE lab.WaitRow SET Value+=1 WHERE RowId=1;EXEC fwk.USP_Signal '$(DemoId)','$(RunToken)','WAITER_COMPLETED';PRINT 'SQLPERF_SUMMARY|PASS|OK';
